local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
------------ import ------------
---@type CatHouseMgr
local CatHouseMgr = import('Game.CatHouse.CatHouseMgr')
local PrefabCellEnvPath = 'Game.CatHouse.Interaction.CatHouseInteractionAttributeNode'
------------ import ------------

------------ define ------------
local PrefabCellName = "CatAttributeNode"
local cardConfMgr = CardConfMgr
------------ define ------------

---@class CatHouseHandbookAttributeAddition
---@field CatAttributeNode                UnityEngine.RectTransform
---@field ListView                        SuperScrollView.LoopListView2
---@field TxtNum                            TMPro.TextMeshProUGUI @进度数据
---@field TxtTitle                        UnityEngine.RectTransform
---@field ClickArea                        UnityEngine.RectTransform
local CatHouseHandbookAttributeAddition = Class("CatHouseHandbookAttributeAddition")

function CatHouseHandbookAttributeAddition:__init()
    self.data = nil
    self.dataDict = nil
end

function CatHouseHandbookAttributeAddition:__delete()
    self.data = nil
    self.dataDict = nil
    self.controller = nil
end

function CatHouseHandbookAttributeAddition:Awake()
    if not isNull(self.ClickArea) then
        SetButtonAction(self.ClickArea, function()
            UIModule.BackDialog()
        end)
    end
    ---锁定去除
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local progress = component:GetAllUnlockGenesAttributeAddition()
    ----测试显示
    --local max = CatHouseMgr:GetInstance():GetAllSettingGenesAttributeAddition()
    local t = {}
    for _, vo in pairs(progress) do
        for i, additionId in pairs(vo.variationKindList) do
            if not t[tostring(additionId)] then
                t[tostring(additionId)] = checkNumber(vo.variationNumList[i])
            else
                t[tostring(additionId)] = checkNumber(t[tostring(additionId)] + checkNumber(vo.variationNumList[i]))
            end
        end
    end
    self.dataDict = t
    self.data = table.keys(t)
    table.sort(self.data)
end

function CatHouseHandbookAttributeAddition:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---已解锁的战中属性的信息
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        local progress = component:GetAllUnlockGenesAttributeAddition()
        local max = CatHouseMgr:GetInstance():GetAllSettingGenesAttributeAddition()
        self.TxtNum.text = string.format('%d/%d', #progress, #max)
        if not self.ListView.IsListViewInit then
            self.ListView:InitListView(#self.data, Bind(self, self.OnGetItemByIndex))
        else
            GameUtils.ReloadData(self.ListView, #self.data)
        end
    end))
    return coWait
end

---OnGetItemByIndex
---@param listView SuperScrollView.LoopListView2
---@param index number
---@return SuperScrollView.LoopListView2
function CatHouseHandbookAttributeAddition:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(PrefabCellName)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
    end
    local position = (index + 1)
    local additionId = self.data[position]
    self:RefreshAttrNode(cell, additionId, position)
    return cell
end

---RefreshAttrNode
---@param cell UnityEngine.GameObject
---@param additionId number
---@param position number 位置
function CatHouseHandbookAttributeAddition:RefreshAttrNode(cell, additionId, position)
    ---@type CatHouseInteractionAttributeNode
    local env = CfUtils.GetLuaScr(cell, PrefabCellEnvPath)
    if isNull(env) then
        return
    end

    local attributeVo = cardConfMgr:GetInstance():GetBasicAttrByBasicAttrAdditionId(additionId)
    if attributeVo then
        env:FreshBaseUI({ name = attributeVo.name, picture = attributeVo.icon}, position)
        env:FreshAttrValue({ num =  '+'.. attribute_format(attributeVo.isConversion, self.dataDict[tostring(additionId)])})
    end
end

function CatHouseHandbookAttributeAddition:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return CatHouseHandbookAttributeAddition